import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.CBxkvBm_.js";const h=JSON.parse('{"title":"Abstract Interpretation, Polyhedral Domains & Continuous Reachability","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms/abstract-interpretation.md","filePath":"algorithms/abstract-interpretation.md"}'),r={name:"algorithms/abstract-interpretation.md"};function n(s,a,l,c,d,m){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="abstract-interpretation-polyhedral-domains-continuous-reachability" tabindex="-1">Abstract Interpretation, Polyhedral Domains &amp; Continuous Reachability <a class="header-anchor" href="#abstract-interpretation-polyhedral-domains-continuous-reachability" aria-label="Permalink to &quot;Abstract Interpretation, Polyhedral Domains &amp; Continuous Reachability&quot;">​</a></h1><p><strong>Implementation</strong>:</p><ul><li>Abstract Interpretation Domains: <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/formal/abstract_interpretation/" target="_blank" rel="noreferrer"><code>packages/runtime/src/formal/abstract_interpretation/</code></a></li><li>DDE Method-of-Steps Flowpipes: <code>DdeFlowpipeSolver</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/analysis/wasm_dde_flowpipe.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/analysis/wasm_dde_flowpipe.ts</code></a></li><li>Hamilton-Jacobi-Isaacs (HJI) Level-Set Solver: <code>HjiLevelSetSolver</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/analysis/wasm_hji_solver.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/analysis/wasm_hji_solver.ts</code></a></li></ul><hr><h2 id="_1-bourdoncle-weak-topological-ordering-wto-fixpoint-solver" tabindex="-1">1. Bourdoncle Weak Topological Ordering (WTO) Fixpoint Solver <a class="header-anchor" href="#_1-bourdoncle-weak-topological-ordering-wto-fixpoint-solver" aria-label="Permalink to &quot;1. Bourdoncle Weak Topological Ordering (WTO) Fixpoint Solver&quot;">​</a></h2><h3 id="academic-citations" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Bourdoncle, F. (1993)</strong>. <em>&quot;Efficient chaotic iteration strategies with widenings.&quot;</em><br><strong>Formal Methods in Programming and Their Applications</strong>, LNCS 735, pp. 128–141. DOI: <a href="https://doi.org/10.1007/BFb0039704" target="_blank" rel="noreferrer">10.1007/BFb0039704</a></li><li><strong>Cousot, P., &amp; Cousot, R. (1977)</strong>. <em>&quot;Abstract interpretation: A unified lattice model for static analysis of programs by construction or approximation of fixpoints.&quot;</em><br><strong>ACM POPL&#39;77</strong>, pp. 238–252. DOI: <a href="https://doi.org/10.1145/512950.512973" target="_blank" rel="noreferrer">10.1145/512950.512973</a></li></ul><h3 id="modelscript-rationale-modifications" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Computes sound abstract over-approximations of state variables across complex nested loops and recursion without simulating unbounded trajectories.</p><ul><li><strong>Modifications</strong>: Implements Bourdoncle&#39;s recursive hierarchical WTO decomposition to identify minimal loop heads; accelerates convergence using delayed widening ($\\nabla$) followed by monotonic narrowing ($\\Delta$).</li></ul><hr><h2 id="_2-two-variables-per-inequality-tvpi-polyhedral-domain" tabindex="-1">2. Two Variables Per Inequality (TVPI) Polyhedral Domain <a class="header-anchor" href="#_2-two-variables-per-inequality-tvpi-polyhedral-domain" aria-label="Permalink to &quot;2. Two Variables Per Inequality (TVPI) Polyhedral Domain&quot;">​</a></h2><h3 id="academic-citations-1" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-1" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Simon, A., King, A., &amp; Howe, J. M. (2002)</strong>. <em>&quot;Two Variables per Inequality as an Abstract Domain.&quot;</em><br><strong>LOPSTR 2002</strong>, LNCS 2664, pp. 71–89. DOI: <a href="https://doi.org/10.1007/3-540-36388-2_7" target="_blank" rel="noreferrer">10.1007/3-540-36388-2_7</a></li><li><strong>Nelson, G. (1978)</strong>. <em>&quot;An $n^{O(\\log n)}$ algorithm for the two-variable-per-inequality integer programming problem.&quot;</em><br><strong>Technical Report</strong>, Stanford University.</li></ul><h3 id="modelscript-rationale-modifications-1" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-1" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Captures planar relational linear invariants of the form: $$a x_i + b x_j \\le c \\quad (a, b, c \\in \\mathbb{Q})$$ Much more expressive than simple intervals or octagons, allowing ModelScript to prove physical conservation laws (e.g. $p_1 + p_2 = \\text{const}$) without the exponential vertex-facet explosion of general convex polyhedra.</p><ul><li><strong>Modifications</strong>: Planar Graham-scan convex hull algorithms in WebAssembly typed memory; relational projection routines optimized for physical parameter spaces.</li></ul><hr><h2 id="_3-octagon-difference-bound-matrices-dbm-domain" tabindex="-1">3. Octagon Difference Bound Matrices (DBM) Domain <a class="header-anchor" href="#_3-octagon-difference-bound-matrices-dbm-domain" aria-label="Permalink to &quot;3. Octagon Difference Bound Matrices (DBM) Domain&quot;">​</a></h2><h3 id="academic-citations-2" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-2" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Miné, A. (2006)</strong>. <em>&quot;The octagon abstract domain.&quot;</em><br><strong>Higher-Order and Symbolic Computation</strong>, 19(1), pp. 31–100.<br> DOI: <a href="https://doi.org/10.1007/s10990-006-8609-1" target="_blank" rel="noreferrer">10.1007/s10990-006-8609-1</a></li></ul><h3 id="modelscript-rationale-modifications-2" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-2" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Restricts linear relationships to constraints of the form: $$\\pm x_i \\pm x_j \\le c$$ Achieves cubic time complexity $\\mathcal{O}(n^3)$ via Floyd-Warshall shortest path algorithms over $2n \\times 2n$ potential graphs.</p><ul><li><strong>Modifications</strong>: Direct integration into the <code>@modelscript/dsl</code> type inference system and <code>AbstractDomainOracle</code> in the Nelson-Oppen coordinator.</li></ul><hr><h2 id="_4-array-segment-partitioning" tabindex="-1">4. Array Segment Partitioning <a class="header-anchor" href="#_4-array-segment-partitioning" aria-label="Permalink to &quot;4. Array Segment Partitioning&quot;">​</a></h2><h3 id="academic-citations-3" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-3" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Cousot, P., Cousot, R., &amp; Logozzo, F. (2011)</strong>. <em>&quot;A Parametric Segmentation Functor for Fully Automatic and Scalable Array Content Analysis.&quot;</em><br><strong>ACM POPL&#39;11</strong>, pp. 505–518. DOI: <a href="https://doi.org/10.1145/1926385.1926444" target="_blank" rel="noreferrer">10.1145/1926385.1926444</a></li></ul><h3 id="modelscript-rationale-modifications-3" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-3" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Verifies large array equations and indexed multi-dimensional components in Modelica without unrolling every array index into separate scalar variables. Partitions index sets into contiguous segments whose bounds and elements share uniform properties.</p><hr><h2 id="_5-delay-differential-equation-dde-method-of-steps-flowpipes-wasm-dde-flowpipe-ts" tabindex="-1">5. Delay Differential Equation (DDE) Method-of-Steps Flowpipes (<code>wasm_dde_flowpipe.ts</code>) <a class="header-anchor" href="#_5-delay-differential-equation-dde-method-of-steps-flowpipes-wasm-dde-flowpipe-ts" aria-label="Permalink to &quot;5. Delay Differential Equation (DDE) Method-of-Steps Flowpipes (`wasm_dde_flowpipe.ts`)&quot;">​</a></h2><h3 id="academic-citations-4" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-4" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Bellman, R., &amp; Cooke, K. L. (1963)</strong>. <em>Differential-Difference Equations.</em><br><strong>Academic Press</strong>.</li><li><strong>Zou, L., Fränzle, M., Xue, B., &amp; Zhan, N. (2015)</strong>. <em>&quot;orda: An Ode and Dde Reachability Analysis Tool.&quot;</em><br><strong>SETTA 2015</strong>, LNCS 9409, pp. 109–123. DOI: <a href="https://doi.org/10.1007/978-3-319-25942-0_8" target="_blank" rel="noreferrer">10.1007/978-3-319-25942-0_8</a></li></ul><h3 id="modelscript-rationale-modifications-4" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-4" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Physical transport delays, networked control loops, and Modelica <code>delay(x, tau)</code> operators yield infinite-dimensional Delay Differential Equations (DDEs): $$\\dot{x}(t) = f\\big(t, x(t), x(t - \\tau)\\big), \\qquad x(t) \\in \\Phi(t) \\text{ for } t \\in [-\\tau, 0]$$ <code>DdeFlowpipeSolver</code> (<code>packages/runtime/src/analysis/wasm_dde_flowpipe.ts</code>) implements <strong>Method-of-Steps</strong> reachability propagation across consecutive delay horizons $[0, \\tau], [\\tau, 2\\tau], \\dots$:</p><ul><li><strong>History Interval Buffering</strong>: Maintains a timestamped ring buffer <code>historyMap</code> storing both nominal trajectories $\\bar{x}(t)$ and interval/zonotope tube enclosures $\\mathcal{X}(t) = [\\underline{x}(t), \\overline{x}(t)]$. For $t - \\tau \\le t_0$, queries evaluate the initial functional history enclosure $\\Phi(t - \\tau)$; for $t - \\tau &gt; t_0$, historical enclosures are interpolated from stored flowpipe steps.</li><li><strong>Interval Picard Enclosure Step</strong>: Advances the state tube across $[t_k, t_k + \\Delta t]$ by combining current state bounds $\\mathcal{X}(t_k)$ and delayed history bounds $\\mathcal{X}(t_k - \\tau)$: $$\\mathcal{X}(t_{k+1}) = \\mathcal{X}(t_k) + \\Delta t \\cdot \\square f\\big(t_k, \\mathcal{X}(t_k), \\mathcal{X}(t_k - \\tau)\\big)$$</li><li><strong>Epistemic Soundness Tagging</strong>: Explicitly tags the resulting <code>VerificationVerdict</code> with rigor metadata (<code>heuristic</code> vs. <code>certified</code>) so downstream safety monitors distinguish fast corner-sampled delay tube estimates from fully Taylor-enclosed flowpipes.</li></ul><hr><h2 id="_6-hamilton-jacobi-isaacs-hji-pde-level-set-reachability-wasm-hji-solver-ts" tabindex="-1">6. Hamilton-Jacobi-Isaacs (HJI) PDE Level-Set Reachability (<code>wasm_hji_solver.ts</code>) <a class="header-anchor" href="#_6-hamilton-jacobi-isaacs-hji-pde-level-set-reachability-wasm-hji-solver-ts" aria-label="Permalink to &quot;6. Hamilton-Jacobi-Isaacs (HJI) PDE Level-Set Reachability (`wasm_hji_solver.ts`)&quot;">​</a></h2><h3 id="academic-citations-5" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-5" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Mitchell, I. M., Bayen, A. M., &amp; Tomlin, C. J. (2005)</strong>. <em>&quot;A time-dependent Hamilton-Jacobi formulation of reachable sets for continuous dynamic games.&quot;</em><br><strong>IEEE Transactions on Automatic Control</strong>, 50(7), pp. 947–957.<br> DOI: <a href="https://doi.org/10.1109/TAC.2005.851439" target="_blank" rel="noreferrer">10.1109/TAC.2005.851439</a></li><li><strong>Jiang, G. S., &amp; Shu, C. W. (2000)</strong>. <em>&quot;Weighted ENO schemes for Hamilton-Jacobi equations.&quot;</em><br><strong>SIAM Journal on Scientific Computing</strong>, 21(6), pp. 2126–2143.<br> DOI: <a href="https://doi.org/10.1137/S106482759732455X" target="_blank" rel="noreferrer">10.1137/S106482759732455X</a></li></ul><h3 id="modelscript-rationale-modifications-5" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-5" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>When verifying safety of nonlinear control systems under worst-case adversarial disturbances $d \\in \\mathcal{D}$ and control authority $u \\in \\mathcal{U}$, convex set-propagation (zonotopes) can suffer from wrapping effects. <code>HjiLevelSetSolver</code> (<code>packages/runtime/src/analysis/wasm_hji_solver.ts</code>) computes the exact <strong>Backward Reachable Tube (BRT)</strong> by solving the zero-sum differential game <strong>Hamilton-Jacobi-Isaacs (HJI) PDE</strong> viscosity solution on an Eulerian level-set grid: $$\\frac{\\partial V}{\\partial t} + \\min \\left{ 0, ; \\min_{u \\in \\mathcal{U}} \\max_{d \\in \\mathcal{D}} \\nabla V(x, t) \\cdot f(x, u, d) \\right} = 0, \\qquad V(x, 0) = \\ell(x)$$ where the sub-zero level set $\\mathcal{K}<em>{\\text{unsafe}} = { x \\mid \\ell(x) \\le 0 }$ defines the target failure region and ${ x \\mid V(x, T) \\le 0 }$ captures all initial states from which the adversary $d$ can force the trajectory into $\\mathcal{K}</em>{\\text{unsafe}}$ within horizon $T$ despite optimal safety control $u$.</p><ul><li><strong>5th-Order WENO Upwind Spatial Reconstruction (<code>weno5Derivatives</code>)</strong>: Approximates left and right spatial derivatives $(p^-, p^+)$ along each state axis using 3-stencil smoothness indicators ($s_1, s_2, s_3$) and nonlinear weights $a_k = \\frac{\\gamma_k}{(\\epsilon + s_k)^2}$, eliminating spurious oscillations near non-smooth value-function kinks.</li><li><strong>Lax-Friedrichs Numerical Hamiltonian</strong>: Evaluates the saddle-point Hamiltonian $H(x, p) = \\min_{u \\in \\mathcal{U}} \\max_{d \\in \\mathcal{D}} p \\cdot f(x, u, d)$ at central gradients $p = \\frac{1}{2}(p^- + p^+)$ augmented by artificial viscosity dissipation: $$\\hat{H}(x, p^-, p^+) = H\\left(x, \\frac{p^- + p^+}{2}\\right) - \\frac{1}{2} \\sum_{i} \\alpha_i (p_i^+ - p_i^-), \\qquad \\alpha_i = \\max_{u, d} |f_i(x, u, d)|$$</li><li><strong>Monotone BRT Accumulation</strong>: Steps the level-set array backward in time with <code>nextV[idx] = Math.min(V[idx], V[idx] - dt * dVdt)</code> and reports the exact unsafe volume fraction across the state space.</li></ul><hr><h2 id="upstream-downstream-pipeline-connections" tabindex="-1">Upstream &amp; Downstream Pipeline Connections <a class="header-anchor" href="#upstream-downstream-pipeline-connections" aria-label="Permalink to &quot;Upstream &amp; Downstream Pipeline Connections&quot;">​</a></h2><ul><li><strong>Upstream Inputs</strong>: <ul><li>Control-flow graphs, <code>delay(x, tau)</code> equations, and continuous vector fields from <code>ModelicaFlattener</code>.</li><li>Adversarial disturbance bounds $\\mathcal{D}$ and safety level-set specifications $\\ell(x) \\le 0$ from SysML v2 verification cases.</li></ul></li><li><strong>Downstream Consumers</strong>: <ul><li>Feeds numeric intervals into <a href="./theory-coordinator.html"><code>HC4 Contractor</code></a> and <a href="./theory-coordinator.html"><code>Nelson-Oppen Coordinator</code></a>.</li><li>Certifies backward reachable tubes and delay flowpipes in <code>UnifiedVerifier</code> (<code>msx verify</code>).</li><li>Eliminates out-of-bounds array access and division-by-zero compiler warnings at compile time.</li></ul></li></ul>',47)])])}const u=e(r,[["render",n]]);export{h as __pageData,u as default};
